class LmdbDeferredEstimatorProcessTerminationTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI PREDICATE = VF.createIRI("urn:deferred-termination:p");

	@Test
	void bufferedCommitBeforeDeferredSetupCannotLeaveAnOldSnapshotCurrent(
			@TempDir(cleanup = CleanupMode.NEVER) Path evidence) throws Exception {
		Path directory = evidence.resolve("store");
		seedSnapshot(directory);
		Path snapshot = directory.resolve("join-estimator.rjes/synopsis-v8.bin");
		Path backup = evidence.resolve("original-v8-backup.bin");
		Files.copy(snapshot, backup);
		Path output = evidence.resolve("child-output.txt");
		String java = Path.of(System.getProperty("java.home"), "bin", "java").toString();
		Process child = new ProcessBuilder(java, "-cp", System.getProperty("java.class.path"),
				CommitThenHalt.class.getName(), directory.toString()).redirectErrorStream(true)
						.redirectOutput(output.toFile())
						.start();
		try {
			assertTrue(child.waitFor(30, TimeUnit.SECONDS), "the child must finish its native commit");
			assertEquals(0, child.exitValue(), Files.readString(output, StandardCharsets.UTF_8));
		} finally {
			if (child.isAlive()) {
				child.destroyForcibly();
				child.waitFor();
			}
		}
		assertTrue(Files.readString(output, StandardCharsets.UTF_8).contains("NATIVE_COMMIT_COMPLETE"));
		boolean markerBeforeRestart = Files.isRegularFile(directory.resolve("join-estimator.rjes/synopsis-v8.rebuild"));
		assertEquals(-1L, Files.mismatch(snapshot, backup), "the child must preserve the original v8 snapshot");
		LmdbStore store = new LmdbStore(directory.toFile(), config());
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
			assertTrue(store.awaitSketchesReady(30, TimeUnit.SECONDS));
			long rows;
			try (var connection = repository.getConnection()) {
				rows = connection.size();
			}
			SketchBasedJoinEstimator estimator = store.getBackingStore().getSketchBasedJoinEstimator();
			QuadProbe probe = new QuadProbe(QuadProbe.PREDICATE, QuadProbe.OBJECT, 0L,
					QuadValueHash.hash(PREDICATE), 0L, 0L, estimator.quadSnapshotIdentity());
			var estimate = estimator.synopsisService().probe(probe);
			assertAll("a committed row cannot be paired with an old current synopsis",
					() -> assertTrue(markerBeforeRestart, "the precommit marker must exist before process termination"),
					() -> assertEquals(2L, rows, "the real LMDB transaction must have committed"),
					() -> assertTrue(estimate.usable()),
					() -> assertEquals(2.0d, estimate.rows().estimate()));
		} finally {
			repository.shutDown();
		}
	}

	private static void seedSnapshot(Path directory) throws Exception {
		LmdbStore store = new LmdbStore(directory.toFile(), config());
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
			try (var connection = repository.getConnection()) {
				connection.add(VF.createIRI("urn:deferred-termination:first"), PREDICATE, VF.createLiteral(1));
			}
			assertTrue(store.forceFlushSketchEstimator());
			SketchBasedJoinEstimator estimator = store.getBackingStore().getSketchBasedJoinEstimator();
			estimator.stop();
			estimator.persistIfDirty();
		} finally {
			repository.shutDown();
		}
	}

	private static LmdbStoreConfig config() {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc").setSketchEstimatorEnabled(true)
				.setSketchEstimatorMemoryBudgetBytes(4L * 1024L * 1024L)
				.setBackgroundRawSamplingEnabled(false)
				.setDirectAdjacencyEnabled(false)
				.setValueOverlayEnabled(false)
				.setForceSync(true);
		config.setExperimentalQueryOptimizations(true);
		return config;
	}

	public static final class CommitThenHalt {
		public static void main(String[] args) throws Exception {
			Path directory = Path.of(args[0]);
			CountDownLatch entered = new CountDownLatch(1);
			CountDownLatch release = new CountDownLatch(1);
			AtomicBoolean haltAfterCommit = new AtomicBoolean();
			LmdbStore store = new HeldStore(directory, config(), entered, release, haltAfterCommit);
			SailRepository repository = new SailRepository(store);
			repository.init();
			if (!entered.await(10, TimeUnit.SECONDS)) {
				throw new IllegalStateException("deferred setup was not held");
			}
			try (var connection = repository.getConnection()) {
				connection.begin(IsolationLevels.READ_COMMITTED);
				connection.add(VF.createIRI("urn:deferred-termination:second"), PREDICATE, VF.createLiteral(2));
				haltAfterCommit.set(true);
				connection.commit();
			}
			throw new IllegalStateException("the native commit hook was not reached");
		}
	}

	private static final class HeldStore extends LmdbStore {
		private final CountDownLatch entered;
		private final CountDownLatch release;
		private final AtomicBoolean haltAfterCommit;

		private HeldStore(Path directory, LmdbStoreConfig config, CountDownLatch entered, CountDownLatch release,
				AtomicBoolean haltAfterCommit) {
			super(directory.toFile(), config);
			this.entered = entered;
			this.release = release;
			this.haltAfterCommit = haltAfterCommit;
		}

		@Override
		LmdbSailStore createBackingStore(File directory, StoreProperties properties, LmdbStoreConfig config,
				boolean sketches) throws IOException, SailException {
			return new LmdbSailStore(directory, properties, config, sketches, null,
					(tripleDir, props, settings, values) -> new TripleStore(tripleDir, props, settings, values) {
						@Override
						void startBackgroundIndexRebuild() {
							entered.countDown();
							try {
								release.await();
							} catch (InterruptedException e) {
								Thread.currentThread().interrupt();
								return;
							}
							super.startBackgroundIndexRebuild();
						}

						@Override
						public void commit() throws IOException {
							super.commit();
							if (haltAfterCommit.get()) {
								System.out.println("NATIVE_COMMIT_COMPLETE");
								System.out.flush();
								Runtime.getRuntime().halt(0);
							}
						}
					});
		}
	}
}
